import pytest

from ansible.module_utils.compat.version import LooseVersion


def test_loose_version_cmp_converts_string_and_returns_equal():
    version = LooseVersion("1.2")

    assert version._cmp("1.2") == 0


@pytest.mark.parametrize(
    ("left", "right", "expected"),
    [
        (LooseVersion("1.0"), LooseVersion("2.0"), -1),
        (LooseVersion("2.0"), LooseVersion("1.0"), 1),
    ],
)
def test_loose_version_cmp_orders_loose_versions(left, right, expected):
    assert left._cmp(right) == expected


def test_loose_version_cmp_returns_not_implemented_for_other_types():
    result = LooseVersion("1.0")._cmp(object())

    assert result is NotImplemented
